fn main() {
    let morning = [94, 71, 88, 65, 92, 79, 83];
    let evening = [55, 90, 77, 84, 68, 99];
    fn analyze(marks: &[i32]) {
        let (mut above_90, mut between_80_and_89, mut between_70_and_79, mut below_70) = (0, 0, 0, 0);
        let mut max_mark = i32::MIN;
        let sum: i32 = marks.iter().map(|&x| {
            if x >= 90 { above_90 += 1; }
            else if x >= 80 { between_80_and_89 += 1; }
            else if x >= 70 { between_70_and_79 += 1; }
            else { below_70 += 1; }
            max_mark = max_mark.max(x);
            x
        }).sum();
        let mean = sum / marks.len() as i32;
        println!("Morning");
        println!("{}", above_90);
        println!("{}", between_80_and_89);
        println!("{}", between_70_and_79);
        println!("{}", below_70);
        println!("{}", max_mark);
        println!("{}", mean);
    }
    analyze(&morning);
    analyze(&evening);
}

