    let evening = [55, 90, 77, 84, 68, 99];
    fn analyze(marks: &[i32], name: &str) {
        let (mut above_90, mut between_80_and_89, mut between_70_and_79, mut below_70) = (0, 0, 0, 0);
        let mut max_mark = i32::MIN;
        let sum: i32 = marks.iter().map(|&x| {
            if x >= 90 { above_90 += 1; }
            else if x >= 80 { between_80_and_89 += 1; }
            else if x >= 70 { between_70_and_79 += 1; }
            else { below_70 += 1; }
            max_mark = max_mark.max(x);
            x
        }).sum();
        let mean = sum / marks.len() as i32;
        println!("{}", name);
        println!("{}", above_90);
        println!("{}", between_80_and_89);
        println!("{}", between_70_and_79);
        println!("{}", below_70);
        println!("{}", max_mark);
        println!("{}", mean);
    }
    analyze(&morning, "Morning");
    analyze(&evening, "Evening");
}

fn main() {
    let words = ["ferry", "oxide", "cargo"];
    for &word in words.iter() {
        println!("{}", word);
        let shifted_forward = shift(word, 3);
        println!("{}", shifted_forward);
        let shifted_backward = shift(shifted_forward, -3);
        println!("{}", shifted_backward);
        println!("{}", shifted_forward == word);
        let shifted_forward_13 = shift(word, 13);
        println!("{}", shifted_forward_13);
        let shifted_backwards_13 = shift(shifted_forward_13, -13);
        println!("{}", shifted_backwards_13 == word);
    }
}
fn shift(s: &str, by: isize) -> String {
    s.chars()
        .map(|c| if c.is_ascii_alphabetic() {
            let base = if c.is_ascii_lowercase() { 'a' } else { 'A' } as u8;
            let shifted = ((c as u8 - base + by as u8) % 26) + base;
            shifted as char
        } else {
            c
        })
        .collect()
}

